import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.BXzK3EA4.js";const o="/yocto_build_pipeline.png",k=JSON.parse('{"title":"Day 2: Yocto Architecture, Terminology & Workflow","description":"","frontmatter":{},"headers":[],"relativePath":"day2-yocto-architecture-terminology-workflow.md","filePath":"day2-yocto-architecture-terminology-workflow.md"}'),n={name:"day2-yocto-architecture-terminology-workflow.md"};function l(r,e,c,d,p,h){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="day-2-yocto-architecture-terminology-workflow" tabindex="-1">Day 2: Yocto Architecture, Terminology &amp; Workflow <a class="header-anchor" href="#day-2-yocto-architecture-terminology-workflow" aria-label="Permalink to &quot;Day 2: Yocto Architecture, Terminology &amp; Workflow&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Define the core metadata terms: Recipe, Class, Append, and Layer</li><li>Navigate the Poky source tree and the generated <code>build/</code> directory</li><li>Configure <code>local.conf</code> and <code>bblayers.conf</code> for a customized build</li><li>Explain the 6-stage OpenEmbedded build pipeline orchestrated by BitBake</li><li>Optimize host disk space usage using <code>rm_work</code></li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day1-embedded-linux-yocto-foundations.html">Day 1: Embedded Linux Foundations &amp; Yocto Quickstart</a></li><li>A cloned Poky repository with the build environment initialized</li></ul></div><hr><h2 id="_1-yocto-project-core-terminology" tabindex="-1">1. Yocto Project Core Terminology <a class="header-anchor" href="#_1-yocto-project-core-terminology" aria-label="Permalink to &quot;1. Yocto Project Core Terminology&quot;">​</a></h2><p>Before diving deeper into the build system, you must master the fundamental building blocks of Yocto, collectively known as <strong>Metadata</strong>.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[Metadata] --&gt; B[Recipes .bb]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A --&gt; C[Classes .bbclass]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A --&gt; D[Configuration .conf]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A --&gt; E[Appends .bbappend]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; F(Layers meta-*)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; F</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; F</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt; F</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Term</th><th>Extension</th><th>Definition</th></tr></thead><tbody><tr><td><strong>Recipe</strong></td><td><code>.bb</code></td><td>Logical sets of instructions detailing where to download source code, what patches to apply, how to compile (Make, CMake, Autotools), and how to package output binaries into <code>.ipk</code>/<code>.deb</code>/<code>.rpm</code> archives.</td></tr><tr><td><strong>Class</strong></td><td><code>.bbclass</code></td><td>Shared build logic inherited by recipes using <code>inherit class_name</code> (e.g., <code>inherit autotools</code>, <code>inherit cmake</code>, <code>inherit python3target</code>).</td></tr><tr><td><strong>Append</strong></td><td><code>.bbappend</code></td><td>Extends or modifies an existing recipe without altering the original <code>.bb</code> file. Crucial for overriding upstream settings cleanly.</td></tr><tr><td><strong>Configuration</strong></td><td><code>.conf</code></td><td>Defines global parameters, machine architectures (<code>local.conf</code>), and layer paths (<code>bblayers.conf</code>).</td></tr><tr><td><strong>Layer</strong></td><td><code>meta-*</code></td><td>Logical grouping of related metadata (e.g., <code>meta-arm</code>, <code>meta-raspberrypi</code>, <code>meta-ti</code>). Layers allow modular customization without modifying core OpenEmbedded recipes.</td></tr><tr><td><strong>BitBake</strong></td><td>N/A</td><td>The Python-based task execution engine that parses metadata and orchestrates the dependency graph and compilation process.</td></tr></tbody></table><h3 id="yocto-project-compatible-layers" tabindex="-1">Yocto Project Compatible Layers <a class="header-anchor" href="#yocto-project-compatible-layers" aria-label="Permalink to &quot;Yocto Project Compatible Layers&quot;">​</a></h3><p>The Yocto Project maintains a strict standard for third-party layers. Layers that are &quot;Yocto Project Compatible&quot; are guaranteed to interoperate cleanly without polluting the global namespace or causing unexpected build failures. Search for compatible layers on the <a href="https://layers.openembedded.org/" target="_blank" rel="noreferrer">OpenEmbedded Layer Index</a>.</p><hr><h2 id="_2-poky-source-tree-layout" tabindex="-1">2. Poky Source Tree Layout <a class="header-anchor" href="#_2-poky-source-tree-layout" aria-label="Permalink to &quot;2. Poky Source Tree Layout&quot;">​</a></h2><p>Inspecting the root directory of a cloned Poky repository reveals its internal structure:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>poky/</span></span>
<span class="line"><span>├── bitbake/            # BitBake build engine source code &amp; executable</span></span>
<span class="line"><span>├── documentation/      # Official Yocto manual &amp; asciidoc/sphinx docs</span></span>
<span class="line"><span>├── meta/               # OE-Core metadata (base recipes, classes, conf)</span></span>
<span class="line"><span>├── meta-poky/          # Poky distribution metadata</span></span>
<span class="line"><span>├── meta-yocto-bsp/     # Hardware BSP recipes for reference boards &amp; QEMU</span></span>
<span class="line"><span>├── oe-init-build-env   # Bash initialization script for build environment</span></span>
<span class="line"><span>└── scripts/            # Helper scripts (runqemu, bitbake-layers, devtool)</span></span></code></pre></div><hr><h2 id="_3-deep-dive-into-the-build-directory-build" tabindex="-1">3. Deep Dive into the Build Directory (<code>build/</code>) <a class="header-anchor" href="#_3-deep-dive-into-the-build-directory-build" aria-label="Permalink to &quot;3. Deep Dive into the Build Directory (\`build/\`)&quot;">​</a></h2><p>Executing <code>source oe-init-build-env</code> creates and enters the <code>build/</code> directory, the sandbox where all compilation occurs.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>build/</span></span>
<span class="line"><span>├── conf/               # User configuration directory</span></span>
<span class="line"><span>│   ├── bblayers.conf   # List of active layer paths parsed by BitBake</span></span>
<span class="line"><span>│   └── local.conf      # Local build environment variables</span></span>
<span class="line"><span>├── downloads/          # Downloaded upstream source tarballs &amp; git repositories</span></span>
<span class="line"><span>├── sstate-cache/       # Shared state cache (speeds up rebuilds across builds)</span></span>
<span class="line"><span>└── tmp/                # Temporary build workspace &amp; deploy outputs</span></span>
<span class="line"><span>    ├── work/           # Cross-compilation sandbox per recipe</span></span>
<span class="line"><span>    └── deploy/</span></span>
<span class="line"><span>        ├── images/     # Final binary bootloaders, kernel, dtb &amp; flash images</span></span>
<span class="line"><span>        ├── rpm/        # Built RPM package feeds</span></span>
<span class="line"><span>        └── ipk/        # Built IPK package feeds</span></span></code></pre></div><h3 id="_3-1-conf-local-conf-environment-variables" tabindex="-1">3.1 <code>conf/local.conf</code> (Environment Variables) <a class="header-anchor" href="#_3-1-conf-local-conf-environment-variables" aria-label="Permalink to &quot;3.1 \`conf/local.conf\` (Environment Variables)&quot;">​</a></h3><p><code>local.conf</code> contains the global configuration for your specific build instance.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Target machine architecture</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MACHINE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;qemuarm&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Parallel build concurrency settings (adjust based on your CPU cores)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BB_NUMBER_THREADS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;8&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PARALLEL_MAKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;-j 8&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Package format management (rpm, deb, or ipk)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PACKAGE_CLASSES</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;package_ipk&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Save disk space by removing temp work folders post-build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INHERIT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;rm_work&quot;</span></span></code></pre></div><h3 id="_3-2-conf-bblayers-conf-layer-management" tabindex="-1">3.2 <code>conf/bblayers.conf</code> (Layer Management) <a class="header-anchor" href="#_3-2-conf-bblayers-conf-layer-management" aria-label="Permalink to &quot;3.2 \`conf/bblayers.conf\` (Layer Management)&quot;">​</a></h3><p><code>bblayers.conf</code> tells BitBake which layer directories to include in its search path. When you add a new hardware BSP or software layer, you add it here.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BBLAYERS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ?=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /path/to/poky/meta </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /path/to/poky/meta-poky </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /path/to/poky/meta-yocto-bsp </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /path/to/poky/meta-custom </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">MANAGING LAYERS</p><p>Instead of editing <code>bblayers.conf</code> manually, use the BitBake tool: <code>bitbake-layers add-layer ../meta-raspberrypi</code></p></div><hr><h2 id="_4-the-yocto-build-system-workflow" tabindex="-1">4. The Yocto Build System Workflow <a class="header-anchor" href="#_4-the-yocto-build-system-workflow" aria-label="Permalink to &quot;4. The Yocto Build System Workflow&quot;">​</a></h2><p>The OpenEmbedded build engine executes a strict, multi-stage pipeline for every single recipe it processes. Understanding this pipeline is essential for debugging build failures.</p><p><img src="`+o+'" alt="Yocto OpenEmbedded Build Workflow"></p><h3 id="the-6-core-build-tasks" tabindex="-1">The 6 Core Build Tasks <a class="header-anchor" href="#the-6-core-build-tasks" aria-label="Permalink to &quot;The 6 Core Build Tasks&quot;">​</a></h3><ol><li><strong><code>do_fetch</code></strong>: Obtains source code from remote repositories (Git, HTTP, FTP, Tarballs) specified in <code>SRC_URI</code>.</li><li><strong><code>do_unpack</code></strong>: Extracts the downloaded source files into the recipe&#39;s working directory (<code>tmp/work/...</code>).</li><li><strong><code>do_patch</code></strong>: Automatically applies unified patch files (<code>.patch</code> or <code>.diff</code>) to the extracted source code.</li><li><strong><code>do_configure</code></strong>: Prepares the build system (configures CMake flags, runs <code>./configure</code> scripts, or <code>make menuconfig</code>).</li><li><strong><code>do_compile</code></strong>: Cross-compiles the source code into target binary object files using the cross-toolchain.</li><li><strong><code>do_install</code></strong>: Installs compiled binaries into a staging directory (<code>${D}</code>) mimicking the final target filesystem layout.</li><li><strong><code>do_package</code></strong>: Splits the installed files into granular packages (<code>PN</code>, <code>PN-dev</code>, <code>PN-dbg</code>) based on rules.</li><li><strong><code>do_rootfs</code></strong>: Assembles the selected packages into the final target root filesystem image.</li></ol><hr><h2 id="_5-saving-host-disk-space-the-rm-work-class" tabindex="-1">5. Saving Host Disk Space: The <code>rm_work</code> Class <a class="header-anchor" href="#_5-saving-host-disk-space-the-rm-work-class" aria-label="Permalink to &quot;5. Saving Host Disk Space: The `rm_work` Class&quot;">​</a></h2><p>Yocto builds consume <strong>30 GB to 100+ GB</strong> of disk space because BitBake retains all intermediate build object files inside <code>tmp/work/</code> for debugging purposes.</p><p>If you are low on disk space, you can instruct BitBake to automatically delete the temporary build artifacts for a recipe once that recipe finishes compiling successfully.</p><p>Add this line to <code>conf/local.conf</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INHERIT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;rm_work&quot;</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">DISK SAVINGS IMPACT</p><p>Enabling <code>rm_work</code> reduces host disk consumption from <strong>~100 GB down to ~15 GB</strong>, making Yocto builds manageable on smaller SSD drives. However, it means you cannot easily debug failed compilations post-mortem without rebuilding the specific recipe.</p></div><hr><h2 id="_6-hands-on-lab-exercises" tabindex="-1">6. Hands-On Lab Exercises <a class="header-anchor" href="#_6-hands-on-lab-exercises" aria-label="Permalink to &quot;6. Hands-On Lab Exercises&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">LAB 2.1: Inspecting the Task Environment</p><ol><li>Pick a simple recipe, e.g., <code>zlib</code>.</li><li>List all available tasks for it: <code>bitbake -c listtasks zlib</code></li><li>Execute only the fetch task: <code>bitbake -c fetch zlib</code></li><li>Find where the downloaded file is stored inside the <code>build/downloads/</code> directory.</li></ol></div><div class="tip custom-block"><p class="custom-block-title">LAB 2.2: The Shared State Cache (sstate-cache)</p><ol><li>Run <code>bitbake core-image-minimal</code> (should be fast if you built it in Day 1).</li><li>Clean the build output for the <code>busybox</code> recipe: <code>bitbake -c clean busybox</code></li><li>Rebuild it: <code>bitbake busybox</code>. Notice how fast it is? It pulled the pre-compiled binaries from the <code>sstate-cache</code>.</li><li>Now, clean the sstate cache as well: <code>bitbake -c cleansstate busybox</code></li><li>Rebuild it again: <code>bitbake busybox</code>. Notice it takes much longer because it is actually compiling from source this time.</li></ol></div><hr><h2 id="_7-further-reading" tabindex="-1">7. Further Reading <a class="header-anchor" href="#_7-further-reading" aria-label="Permalink to &quot;7. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Yocto Project Concepts Manual</td><td><a href="https://docs.yoctoproject.org/overview-manual/concepts.html" target="_blank" rel="noreferrer">docs.yoctoproject.org/overview-manual/concepts.html</a></td></tr><tr><td>BitBake Tasks Documentation</td><td><a href="https://docs.yoctoproject.org/bitbake/bitbake-user-manual/bitbake-user-manual-execution.html" target="_blank" rel="noreferrer">docs.yoctoproject.org/bitbake/bitbake-user-manual/bitbake-user-manual-execution.html</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day1-embedded-linux-yocto-foundations">← Day 1: Yocto Foundations</a><a href="/day3-beaglebone-black-hardware-bringup">Day 3: BeagleBone Black Bring-Up →</a></div>',47)])])}const b=a(n,[["render",l]]);export{k as __pageData,b as default};
